let a = UIView(), b = UIView()
[a, b].forEach {
  $0.translatesAutoresizingMaskIntoConstraints = false
  view.addSubview($0)
}

// Anchors — modern API
NSLayoutConstraint.activate([
  a.topAnchor.constraint(equalTo: view.safeAreaLayoutGuide.topAnchor, constant: 16),
  a.leadingAnchor.constraint(equalTo: view.leadingAnchor, constant: 16),
  a.trailingAnchor.constraint(equalTo: view.trailingAnchor, constant: -16),
  a.heightAnchor.constraint(equalToConstant: 80),

  b.topAnchor.constraint(equalTo: a.bottomAnchor, constant: 12),
  b.leadingAnchor.constraint(equalTo: a.leadingAnchor),
  b.trailingAnchor.constraint(equalTo: a.trailingAnchor),
  b.heightAnchor.constraint(equalTo: a.heightAnchor),
])

// Frame-based for comparison — does NOT adapt
let old = UIView(frame: CGRect(x: 16, y: 100, width: view.bounds.width - 32, height: 80))
// ... and you'd have to redo this in viewDidLayoutSubviews on rotation, etc.

// Common pitfalls
// 1) Forgetting translatesAutoresizingMaskIntoConstraints = false — Auto Layout fights
//    autoresizing mask constraints and you get "unable to satisfy".
// 2) Animating layout changes — change constants, then call view.layoutIfNeeded inside
//    UIView.animate to animate to the new positions.

let title = UILabel(); title.text = "Long article title that wraps"
let badge = UILabel(); badge.text = "NEW"

// Title should yield space; badge should hold its size
title.setContentHuggingPriority(.defaultLow, for: .horizontal)
title.setContentCompressionResistancePriority(.defaultLow - 1, for: .horizontal)

badge.setContentHuggingPriority(.required, for: .horizontal)
badge.setContentCompressionResistancePriority(.required, for: .horizontal)

// In a stack
let row = UIStackView(arrangedSubviews: [title, badge])
row.axis = .horizontal
row.spacing = 8
row.alignment = .center

// Custom view with intrinsic size — override
class Pill: UIView {
  let label = UILabel()
  override var intrinsicContentSize: CGSize {
    let s = label.intrinsicContentSize
    return CGSize(width: s.width + 24, height: s.height + 8)
  }
  override init(frame: CGRect) {
    super.init(frame: frame)
    addSubview(label)
  }
  required init?(coder: NSCoder) { fatalError() }
}

// Force re-measurement when content changes
func setText(_ s: String) {
  label.text = s
  invalidateIntrinsicContentSize()
}

// Vertical stack of content
let content = UIStackView(arrangedSubviews: [
  titleLabel,
  subtitleLabel,
  metadataRow,
])
content.axis = .vertical
content.spacing = 8
content.alignment = .leading

// metadataRow itself is a horizontal stack
let metadataRow = UIStackView(arrangedSubviews: [authorLabel, dotLabel, dateLabel])
metadataRow.axis = .horizontal
metadataRow.spacing = 4

// Add to view + constrain only the outer container
view.addSubview(content)
content.translatesAutoresizingMaskIntoConstraints = false
NSLayoutConstraint.activate([
  content.leadingAnchor.constraint(equalTo: view.leadingAnchor, constant: 16),
  content.trailingAnchor.constraint(equalTo: view.trailingAnchor, constant: -16),
  content.topAnchor.constraint(equalTo: view.safeAreaLayoutGuide.topAnchor, constant: 16),
])

// Hide a row — stack collapses the gap
subtitleLabel.isHidden = true

// Custom spacing after a specific child (iOS 11+)
content.setCustomSpacing(20, after: titleLabel)

// .fillEqually distributes children evenly along the axis
let tabs = UIStackView(arrangedSubviews: [tab1, tab2, tab3])
tabs.distribution = .fillEqually

// Pin a button to the bottom safe area (above the home indicator)
view.addSubview(button)
button.translatesAutoresizingMaskIntoConstraints = false
NSLayoutConstraint.activate([
  button.leadingAnchor.constraint(equalTo: view.leadingAnchor, constant: 16),
  button.trailingAnchor.constraint(equalTo: view.trailingAnchor, constant: -16),
  button.bottomAnchor.constraint(equalTo: view.safeAreaLayoutGuide.bottomAnchor, constant: -8),
  button.heightAnchor.constraint(equalToConstant: 50),
])

// Push content down past a custom banner the VC adds
additionalSafeAreaInsets = UIEdgeInsets(top: 56, left: 0, bottom: 0, right: 0)

// React to insets change (rare — rotation / multitasking)
override func safeAreaInsetsDidChange() {
  super.safeAreaInsetsDidChange()
  // adjust custom layouts that read view.safeAreaInsets directly
}

// Edges for extension — old-style API
edgesForExtendedLayout = []  // don't extend under nav/tab bars
extendedLayoutIncludesOpaqueBars = false

// In SwiftUI you reach for safe area via .ignoresSafeArea() and the SafeAreaRegions
// argument to opt into / out of which insets to ignore.

// Name constraints for readable logs
let c = button.bottomAnchor.constraint(equalTo: view.safeAreaLayoutGuide.bottomAnchor, constant: -8)
c.identifier = "buttonBottom"
c.isActive = true

// Make an optional constraint break gracefully
let preferred = label.widthAnchor.constraint(equalToConstant: 200)
preferred.priority = .defaultHigh    // 750 — broken before required (1000)
preferred.isActive = true

// Detect ambiguous layout in dev
#if DEBUG
DispatchQueue.main.async {
  if view.hasAmbiguousLayout { view.exerciseAmbiguityInLayout() }
}
#endif

// Symbolic breakpoint setup (Xcode):
// 1. Breakpoints navigator → +Symbolic Breakpoint
// 2. Symbol: UIViewAlertForUnsatisfiableConstraints
// When triggered, you can `po [view recursiveDescription]` in the LLDB console.

// Animating constraint changes — must call layoutIfNeeded inside the animation block
leadingConstraint.constant = 100
UIView.animate(withDuration: 0.3) {
  self.view.layoutIfNeeded()
}

// Animate by changing constraint constants
leadingConstraint.constant = 100
view.setNeedsLayout()
UIView.animate(withDuration: 0.3) {
  view.layoutIfNeeded()           // forces the new layout to apply inside the animation
}

// Custom subview layout — override layoutSubviews
class GradientView: UIView {
  let gradient = CAGradientLayer()
  override init(frame: CGRect) {
    super.init(frame: frame)
    layer.addSublayer(gradient)
  }
  required init?(coder: NSCoder) { fatalError() }
  override func layoutSubviews() {
    super.layoutSubviews()
    gradient.frame = bounds // keep gradient sized with the view
  }
}

// setNeedsLayout vs layoutIfNeeded — pick by intent
func onContentChanged() {
  contentLabel.text = "..."
  setNeedsLayout()         // schedule a relayout
  // layoutIfNeeded() — only call if you need the new frames RIGHT NOW (e.g. in animation block)
}

// Don't call layoutSubviews directly — call setNeedsLayout / layoutIfNeeded.

let card = UIView()
card.translatesAutoresizingMaskIntoConstraints = false   // the line everyone forgets once
view.addSubview(card)
NSLayoutConstraint.activate([
  card.topAnchor.constraint(equalTo: view.safeAreaLayoutGuide.topAnchor, constant: 16),
  card.leadingAnchor.constraint(equalTo: view.leadingAnchor, constant: 16),
  card.trailingAnchor.constraint(equalTo: view.trailingAnchor, constant: -16),
  card.heightAnchor.constraint(equalToConstant: 120),
])

// Left at its default of true, UIKit synthesises constraints from the view's frame
// and autoresizing mask, and they contradict yours:
//   "Unable to simultaneously satisfy constraints ... NSAutoresizingMaskLayoutConstraint"
// A view created in code starts at .zero, so everything lands in the top-left corner.

// Make it hard to forget
extension UIView {
  static func autoLayout() -> Self {
    let view = Self()
    view.translatesAutoresizingMaskIntoConstraints = false
    return view
  }
}
let title = UILabel.autoLayout()

// Do NOT turn it off on views you do not constrain yourself: a view controller's root
// view, a cell's contentView, or anything you position with frames.
// Interface Builder already sets it false, and UIStackView sets it on arranged subviews.

final class MessageCell: UITableViewCell {
  private let title = UILabel()
  private let body = UILabel()

  override init(style: UITableViewCell.CellStyle, reuseIdentifier: String?) {
    super.init(style: style, reuseIdentifier: reuseIdentifier)
    [title, body].forEach {
      $0.numberOfLines = 0                        // 0 = as many lines as the text needs
      $0.translatesAutoresizingMaskIntoConstraints = false
      contentView.addSubview($0)                  // constraints go on contentView, not the cell
    }

    let bottom = body.bottomAnchor.constraint(equalTo: contentView.bottomAnchor, constant: -12)
    bottom.priority = UILayoutPriority(999)       // yields while the cell is briefly unsized

    NSLayoutConstraint.activate([
      title.topAnchor.constraint(equalTo: contentView.topAnchor, constant: 12),
      title.leadingAnchor.constraint(equalTo: contentView.layoutMarginsGuide.leadingAnchor),
      title.trailingAnchor.constraint(equalTo: contentView.layoutMarginsGuide.trailingAnchor),
      body.topAnchor.constraint(equalTo: title.bottomAnchor, constant: 4),
      body.leadingAnchor.constraint(equalTo: title.leadingAnchor),
      body.trailingAnchor.constraint(equalTo: title.trailingAnchor),
      bottom,   // the chain reaches the bottom, so the height is solvable
    ])
  }
  required init?(coder: NSCoder) { fatalError("use init(style:reuseIdentifier:)") }
}

// Both have been the defaults for years, so the flags are rarely the bug — the chain is
tableView.rowHeight = UITableView.automaticDimension
tableView.estimatedRowHeight = 88

// Collection views ask the layout for an estimated dimension
let itemSize = NSCollectionLayoutSize(widthDimension: .fractionalWidth(1),
                                      heightDimension: .estimated(88))

// Verify the computed height in a test instead of by scrolling and squinting
let height = cell.systemLayoutSizeFitting(
  CGSize(width: 390, height: UIView.layoutFittingCompressedSize.height),
  withHorizontalFittingPriority: .required,
  verticalFittingPriority: .fittingSizeLevel).height

private var heightConstraint: NSLayoutConstraint!   // keep the reference, change the constant

func setExpanded(_ expanded: Bool, animated: Bool) {
  heightConstraint.constant = expanded ? 240 : 88
  guard animated else { view.layoutIfNeeded(); return }
  UIView.animate(withDuration: 0.3) { self.view.layoutIfNeeded() }
}

// Structural change: hold both sets and swap them. Never build new ones per update —
// they accumulate invisibly until the layout is both slow and unsatisfiable.
private lazy var compact = [
  image.widthAnchor.constraint(equalToConstant: 44),
  label.leadingAnchor.constraint(equalTo: image.trailingAnchor, constant: 8),
]
private lazy var expanded = [
  image.widthAnchor.constraint(equalTo: card.widthAnchor),
  label.topAnchor.constraint(equalTo: image.bottomAnchor, constant: 8),
]

func applyLayout(isExpanded: Bool) {
  NSLayoutConstraint.deactivate(isExpanded ? compact : expanded)
  NSLayoutConstraint.activate(isExpanded ? expanded : compact)
}

// Priority: let one of two competing constraints win instead of breaking either
let preferredWidth = label.widthAnchor.constraint(equalToConstant: 320)
preferredWidth.priority = .defaultHigh   // 750, so it yields to a required trailing constraint
preferredWidth.isActive = true

// Changing a priority to or from .required on an installed constraint traps at runtime.

// Show and hide inside a stack view without touching constraints at all
detailsLabel.isHidden = !isExpanded

// Three different edges to pin to, with three different meanings
label.leadingAnchor.constraint(equalTo: view.leadingAnchor)                      // literal bounds
label.leadingAnchor.constraint(equalTo: view.layoutMarginsGuide.leadingAnchor)   // plus margins
label.leadingAnchor.constraint(equalTo: view.readableContentGuide.leadingAnchor) // readable width

// Margins are directional, so they mirror in right-to-left languages
view.directionalLayoutMargins = NSDirectionalEdgeInsets(top: 16, leading: 20,
                                                        bottom: 16, trailing: 20)
viewRespectsSystemMinimumLayoutMargins = false   // on a controller, to go below the system floor

// A stack view ignores its own margins until you ask it not to
stack.isLayoutMarginsRelativeArrangement = true
stack.directionalLayoutMargins = .init(top: 12, leading: 16, bottom: 12, trailing: 16)

// A layout guide replaces a transparent spacer view: nothing to draw, no touch target,
// no accessibility element, and no noise in the view debugger
let gutter = UILayoutGuide()
view.addLayoutGuide(gutter)
NSLayoutConstraint.activate([
  gutter.leadingAnchor.constraint(equalTo: left.trailingAnchor),
  gutter.trailingAnchor.constraint(equalTo: right.leadingAnchor),
  gutter.widthAnchor.constraint(greaterThanOrEqualToConstant: 8),
])

// Leading and trailing mirror automatically; left and right never do
NSLayoutConstraint.activate([
  icon.leadingAnchor.constraint(equalTo: view.layoutMarginsGuide.leadingAnchor),
  label.leadingAnchor.constraint(equalTo: icon.trailingAnchor, constant: 8),
  label.trailingAnchor.constraint(lessThanOrEqualTo: view.layoutMarginsGuide.trailingAnchor),
])

// Directional insets mirror; UIEdgeInsets does not
stack.directionalLayoutMargins = .init(top: 8, leading: 16, bottom: 8, trailing: 16)

// A directional glyph has to be told that it may flip
backButton.setImage(UIImage(named: "chevron")?.imageFlippedForRightToLeftLayoutDirection(),
                    for: .normal)
transportControls.semanticContentAttribute = .playback   // media controls must not mirror

// Dynamic Type: a text style plus the opt-in that keeps it updating
label.font = .preferredFont(forTextStyle: .body)
label.adjustsFontForContentSizeCategory = true
label.numberOfLines = 0

// Scale a custom font and a hard-coded spacing with the same metrics
let metrics = UIFontMetrics(forTextStyle: .body)
label.font = metrics.scaledFont(for: brandFont)
spacingConstraint.constant = metrics.scaledValue(for: 16)

// React to a text-size change without overriding the deprecated traitCollectionDidChange
registerForTraitChanges([UITraitPreferredContentSizeCategory.self]) { (self: Self, _) in
  let isHuge = self.traitCollection.preferredContentSizeCategory.isAccessibilityCategory
  self.stack.axis = isHuge ? .vertical : .horizontal
}
